"""TrialResult, ScenarioBenchmarkResult, and reporting helpers."""

from __future__ import annotations

import math
import re
import statistics
from dataclasses import dataclass, field

# Pattern for 8-char hex job IDs generated by AsyncEngine (uuid.uuid4().hex[:8])
_JOB_ID_PATTERN = re.compile(r'\b[0-9a-f]{8}\b')

# Canonical mode ordering for display
MODES = ("sync", "async/tool", "async/system", "async/user")


def _wilson_ci(successes: int, n: int, z: float = 1.96) -> tuple[float, float]:
    """Wilson score 95% CI for a proportion. Returns (lo, hi) in [0, 1].

    At n=5 with 5/5 successes this correctly returns ~(0.55, 1.0) rather
    than the misleading point estimate of 100%.
    """
    if n == 0:
        return (0.0, 1.0)
    p_hat = successes / n
    denominator = 1 + z**2 / n
    centre = (p_hat + z**2 / (2 * n)) / denominator
    margin = (z * math.sqrt(p_hat * (1 - p_hat) / n + z**2 / (4 * n**2))) / denominator
    return (max(0.0, centre - margin), min(1.0, centre + margin))


@dataclass
class TrialResult:
    scenario_name: str
    mode: str
    trial_idx: int

    # Wall-clock timing (seconds)
    total_latency: float          # full wall time from user msg to final response
    ttfr: float                   # time to first response (== total_latency for sync)

    # Deterministic quality checks (no LLM needed)
    success: bool                 # success_marker present in final_response (case-insensitive)
    job_id_leaked: bool           # 8-char hex job ID found in any assistant message

    # Optional LLM-judge scores (0.0–1.0); None when judge is skipped
    synthesis_quality: float | None = None
    context_awareness: float | None = None

    # Raw text of the final synthesised response
    final_response: str = ""

    # Number of OpenAI API calls made during this trial
    num_llm_calls: int = 0


@dataclass
class ScenarioBenchmarkResult:
    scenario_name: str
    mode: str
    trials: list[TrialResult] = field(default_factory=list)

    @property
    def n(self) -> int:
        return len(self.trials)

    @property
    def pass_at_1(self) -> float:
        if not self.trials:
            return 0.0
        return sum(t.success for t in self.trials) / self.n

    @property
    def pass_at_1_ci(self) -> tuple[float, float]:
        """Wilson 95% CI for pass@1. Returns (lo, hi) in [0, 1]."""
        successes = sum(t.success for t in self.trials)
        return _wilson_ci(successes, self.n)

    def pass_k(self, k: int) -> float:
        """pass^k = pass@1 ^ k  (Bernoulli independence assumption)."""
        return self.pass_at_1 ** k

    @property
    def mean_total_latency(self) -> float:
        if not self.trials:
            return 0.0
        return sum(t.total_latency for t in self.trials) / self.n

    @property
    def stdev_total_latency(self) -> float:
        lats = [t.total_latency for t in self.trials]
        return statistics.stdev(lats) if len(lats) > 1 else 0.0

    @property
    def mean_ttfr(self) -> float:
        if not self.trials:
            return 0.0
        return sum(t.ttfr for t in self.trials) / self.n

    @property
    def mean_num_llm_calls(self) -> float:
        if not self.trials:
            return 0.0
        return sum(t.num_llm_calls for t in self.trials) / self.n

    @property
    def leak_rate(self) -> float:
        if not self.trials:
            return 0.0
        return sum(t.job_id_leaked for t in self.trials) / self.n

    @property
    def mean_synthesis_quality(self) -> float | None:
        scores = [t.synthesis_quality for t in self.trials if t.synthesis_quality is not None]
        return sum(scores) / len(scores) if scores else None

    @property
    def mean_context_awareness(self) -> float | None:
        scores = [t.context_awareness for t in self.trials if t.context_awareness is not None]
        return sum(scores) / len(scores) if scores else None


def check_job_id_leaked(messages: list[dict]) -> bool:
    """Return True if any assistant message contains an 8-char hex job ID."""
    for msg in messages:
        if msg.get("role") == "assistant" and msg.get("content"):
            if _JOB_ID_PATTERN.search(msg["content"]):
                return True
    return False


def print_results_table(results: list[ScenarioBenchmarkResult], k: int = 5) -> None:
    """Print a human-readable results table grouped by scenario."""
    scenarios = list(dict.fromkeys(r.scenario_name for r in results))  # preserve order
    for scenario in scenarios:
        group = [r for r in results if r.scenario_name == scenario]
        if not group:
            continue

        n = group[0].n
        header_label = f"{scenario}  [n={n}]"
        print(f"\n{'━' * 4} {header_label} {'━' * max(2, 60 - len(header_label))}")
        col_w = 14
        print(f"  {'Metric':<28}" + "".join(f"{r.mode:>{col_w}}" for r in group))
        print("  " + "─" * (28 + col_w * len(group)))

        def row(label: str, vals: list[str]) -> None:
            print(f"  {label:<28}" + "".join(f"{v:>{col_w}}" for v in vals))

        row("Total latency (s)",
            [f"{r.mean_total_latency:.1f} ±{r.stdev_total_latency:.1f}" for r in group])
        row("TTFR (s)", [f"{r.mean_ttfr:.1f}" for r in group])
        row("LLM calls (mean)", [f"{r.mean_num_llm_calls:.1f}" for r in group])
        row("Pass@1", [f"{r.pass_at_1:.0%}" for r in group])
        row("  95% CI",
            ["[{:.0%}–{:.0%}]".format(*r.pass_at_1_ci) for r in group])
        row(f"Pass^{k}", [f"{r.pass_k(k):.0%}" for r in group])
        row("Job ID leaked", [f"{r.leak_rate:.0%}" for r in group])

        sq = [r.mean_synthesis_quality for r in group]
        if any(v is not None for v in sq):
            row("Synthesis quality", [f"{v:.2f}" if v is not None else "—" for v in sq])

        ca = [r.mean_context_awareness for r in group]
        if any(v is not None for v in ca):
            row("Context awareness", [f"{v:.2f}" if v is not None else "—" for v in ca])
